// Parseia evento do ClickUp
const body = $input.item.json;
const event = body.event; // 'taskCreated' | 'taskUpdated' | 'taskDeleted'
const task = body.task_id;
const historyItems = body.history_items || [];

if (!task) return [{ json: { skip: true, reason: 'no task_id' } }];

// Detecta tipo de mudança
const isDeleted = event === 'taskDeleted';
const isCreated = event === 'taskCreated';

// Extrai campos alterados
let title = null, description = null, startDate = null, dueDate = null;
for (const h of historyItems) {
  if (h.field === 'name') title = h.after;
  if (h.field === 'description') description = h.after;
  if (h.field === 'start_date') startDate = h.after ? new Date(parseInt(h.after)).toISOString() : null;
  if (h.field === 'due_date') dueDate = h.after ? new Date(parseInt(h.after)).toISOString() : null;
}

return [{ json: {
  event,
  clickup_task_id: task,
  is_deleted: isDeleted,
  is_created: isCreated,
  title,
  description,
  start_at: startDate,
  end_at: dueDate,
  skip: false
}}];

// Enriquece com dados completos da task
const task = $input.item.json;
const prev = $('Parsear Evento ClickUp').item.json;

const startMs = task.start_date ? parseInt(task.start_date) : null;
const dueMs = task.due_date ? parseInt(task.due_date) : null;

// Extrai IDs externos dos custom fields
const customFields = task.custom_fields || [];
const maestriaField = customFields.find(f => f.name === 'Maestr.ia ID');
const maestriaId = maestriaField?.value || null;

return [{ json: {
  ...prev,
  title: task.name || prev.title,
  description: task.description || prev.description || '',
  start_at: startMs ? new Date(startMs).toISOString() : prev.start_at,
  end_at: dueMs ? new Date(dueMs).toISOString() : prev.end_at,
  maestria_id: maestriaId,
  tags: (task.tags || []).map(t => t.name)
}}];

// Decide se cria ou atualiza no Maestr.ia
const events = $input.item.json;
const prev = $('Enriquecer Dados da Task').item.json;

const existing = Array.isArray(events) && events.length > 0 ? events[0] : null;

return [{ json: {
  ...prev,
  maestria_id: existing?.id || prev.maestria_id || null,
  gcal_event_id: existing?.gcal_event_id || null,
  action: existing ? 'update' : 'create'
}}];

// Após criar/atualizar no Maestr.ia, sincroniza para Google Calendar
const result = $input.item.json;
const prev = $('Decidir Ação').item.json;
const gcalEventId = prev.gcal_event_id;

return [{ json: {
  ...prev,
  maestria_id: result.id || prev.maestria_id,
  gcal_event_id: gcalEventId,
  gcal_action: gcalEventId ? 'update' : 'create'
}}];
